exercises.starterCode:
// Declare a variable called message using let
// Assign it the value "Hello, world!"

// Declare a constant called year using const
// Assign it the value 2026

exercises.testRunner:
(code) => {
  const r = new Function(code + '; return { message, year };')();
  return [
    { pass: r.message === 'Hello, world!', description: 'message is "Hello, world!"', got: String(r.message) },
    { pass: r.year === 2026, description: 'year is 2026', got: String(r.year) },
    { pass: typeof r.message === 'string', description: 'message is a string', got: typeof r.message },
    { pass: typeof r.year === 'number', description: 'year is a number', got: typeof r.year }
  ];
}

