exercises.instructions:
The `.forEach()` method does the same thing as a `for` loop — it visits every element in an array. Here is the conversion pattern:

**For loop:**
```js
for (let i = 0; i < words.length; i++) {
  result.push(words[i].toUpperCase());
}
```

**forEach:**
```js
words.forEach(function(word) {
  result.push(word.toUpperCase());
});
```

Rewrite the for loop inside `shoutAll` using `.forEach()` instead.

Example: `shoutAll(["hi", "bye"])` returns `["HI", "BYE"]`

exercises.starterCode:
function shoutAll(words) {
  const result = [];

  // The for loop below works, but rewrite it using .forEach()
  //
  //   for (let i = 0; i < words.length; i++) {
  //     result.push(words[i].toUpperCase());
  //   }
  //
  // Step 1: Call words.forEach()
  // Step 2: Pass a function that takes one word
  // Step 3: Inside, push word.toUpperCase() into result


  return result;
}

exercises.solution:
function shoutAll(words) {
  const result = [];
  words.forEach(function(word) {
    result.push(word.toUpperCase());
  });
  return result;
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return shoutAll;')();
  const r1 = fn(['hi', 'bye']);
  const r2 = fn(['hello']);
  const r3 = fn([]);
  return [
    { pass: JSON.stringify(r1) === JSON.stringify(['HI', 'BYE']), description: 'shoutAll(["hi", "bye"]) returns ["HI", "BYE"]', got: JSON.stringify(r1) },
    { pass: JSON.stringify(r2) === JSON.stringify(['HELLO']), description: 'shoutAll(["hello"]) returns ["HELLO"]', got: JSON.stringify(r2) },
    { pass: JSON.stringify(r3) === JSON.stringify([]), description: 'shoutAll([]) returns []', got: JSON.stringify(r3) },
    { pass: code.includes('.forEach'), description: 'Uses .forEach() method', got: code.includes('.forEach') ? 'Yes' : 'No' }
  ];
}

