exercises.solution:
function validateTypes(data, schema) {
  const keys = Object.keys(schema);
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    if (typeof data[key] !== schema[key]) {
      return false;
    }
  }
  return true;
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return validateTypes;')();
  const schema = { name: 'string', age: 'number' };
  return [
    { pass: fn({ name: 'Alice', age: 25 }, schema) === true, description: 'Valid data returns true', got: String(fn({ name: 'Alice', age: 25 }, schema)) },
    { pass: fn({ name: 'Alice', age: '25' }, schema) === false, description: 'Wrong type (string age) returns false', got: String(fn({ name: 'Alice', age: '25' }, schema)) },
    { pass: fn({ name: 'Alice' }, schema) === false, description: 'Missing field returns false', got: String(fn({ name: 'Alice' }, schema)) }
  ];
}

